INSERT INTO punchlines (id, created_by, updated_by, line) VALUES
    ('punchlines-12345678901234567890119', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'A voice broke through the thunder and the rain as the paint ran down the church walls, saying, "Repaint! And thin no more!"'),
    ('punchlines-12345678901234567890120', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'The second string said to the bartender, "You''ll have to excuse my buddy here … he''s not NULL Terminated."'),
    ('punchlines-12345678901234567890121', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'The bar tender exclaimed. "Hey! Aren''t you that string I told to get lost?" The string said to the bar tender, "No sir! I''m a frayed knot!"'),
    ('punchlines-12345678901234567890122', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', '"Oh yes he does," the first kid says to the other. "I''ve seen the cigarette stians on his underwear."'),
    ('punchlines-12345678901234567890123', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'She looked surprised.'),
    ('punchlines-12345678901234567890124', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'I now live in constant fear.'),
    ('punchlines-12345678901234567890125', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'Because they make up everything.'),
    ('punchlines-12345678901234567890126', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'My computer said "No problem, I''ll go to sleep."'),
    ('punchlines-12345678901234567890127', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'She whispered, "They''re right behind you."')
